// Package seeders contains all database seeders for this GoForge application.
//
// # Structure
//
//   - database_seeder.go  — The root seeder. Called by default when running db:seed.
//     Add new child seeders here by calling database.Call(db, &YourSeeder{}).
//   - registry.go         — (this file) Imports every seeder file so their init()
//     functions fire and register them into the global registry.
//   - <name>_seeder.go    — Individual seeders generated by goforge gen:seeder.
//
// # Usage
//
//	# Run all seeders (via DatabaseSeeder):
//	goforge db:seed
//
//	# Run a single seeder by name:
//	goforge db:seed --class=TodoSeeder
//
//	# Generate a new seeder:
//	goforge gen:seeder <name>
package seeders

// RegisterAll is called by the db:seed command to ensure every seeder's
// init() has been executed and its seeder is in the global registry.
//
// Import every new *_seeder.go file here by adding a blank import or by
// referencing a symbol from it. Using a named import that points at the
// package itself is the simplest approach because adding new files to
// this package is enough — no change to RegisterAll is required.
//
// Each seeder file already calls database.Register(&XxxSeeder{}) in its
// own init(), so merely importing this package (which in turn imports the
// seeder files) is sufficient.
func RegisterAll() {
	// This function intentionally left empty.
	// Its sole purpose is to give callers a single symbol to import so that
	// all seeder init() functions run before the seed command executes.
	//
	// To add a new seeder:
	//   1. Run:  goforge gen:seeder <name>
	//   2. Open  internal/database/seeders/<name>_seeder.go  and fill in Run().
	//   3. Add   &YourSeeder{}  to DatabaseSeeder.Run() below.
	//
	// No changes to this file are needed.
}
